import { $,root,Engine,clearError,showError,progress,cell,badge,wireDownloads,enableDownloads } from '../tools-ui.js';
let result=null,busy=false,engine,ocrWorker,pdfLib,sourceFiles=[],selectedRecord,previewDoc,previewBusy=false;
const samples=[['INV_A_tsubame_tsushin.pdf',false],['INV_B_himawari_kokoku.pdf',false],['INV_C_aoi_design_scan.pdf',true],['INV_D_kamome_fudosan_scan.pdf',true],['INV_E_kobato_bungu.pdf',false]];
const currency=value=>value==null?'—':'¥'+Number(value).toLocaleString('ja-JP');
function buttons(){const upload=document.querySelector('[name=source]:checked').value==='upload';$('run').disabled=busy||!engine?.ready||(upload&&!$('pdf-files').files.length);enableDownloads(!!result&&!busy);}
engine=new Engine(()=>buttons());
function invalidate(){if(busy)return;result=null;enableDownloads(false);$('result-state').textContent='入力・条件を変更しました。再実行してください。';clearError();buttons();}
function lock(value){busy=value;$('settings').classList.toggle('running',value);document.querySelectorAll('#settings input,#settings button:not(#retry)').forEach(el=>el.disabled=value);buttons();}
async function loadPdfLib(){if(!pdfLib){pdfLib=await import(new URL('vendor/pdfjs/pdf.mjs',root));pdfLib.GlobalWorkerOptions.workerSrc=new URL('vendor/pdfjs/pdf.worker.mjs',root).href;}return pdfLib;}
async function openPdf(bytes){const lib=await loadPdfLib();const task=lib.getDocument({data:new Uint8Array(bytes.slice(0)),cMapUrl:new URL('vendor/pdfjs/cmaps/',root).href,cMapPacked:true,standardFontDataUrl:new URL('vendor/pdfjs/standard_fonts/',root).href,wasmUrl:new URL('vendor/pdfjs/wasm/',root).href,isEvalSupported:false});task.onPassword=()=>task.destroy();try{return await task.promise;}catch(e){if(e.name==='PasswordException'||/password/i.test(e.message))throw new Error('暗号化されたPDFです。パスワードなしのPDFを選んでください。');throw new Error('PDFを開けませんでした。ファイルが壊れていないか確認してください。');}}
function textLines(items){const words=items.filter(i=>i.str?.trim()).map(i=>({x:i.transform[4],y:i.transform[5],width:i.width,text:i.str})).sort((a,b)=>b.y-a.y||a.x-b.x);const rows=[];for(const word of words){let row=rows.find(r=>Math.abs(r.y-word.y)<3);if(!row){row={y:word.y,words:[]};rows.push(row);}row.words.push(word);}return rows.map(row=>{row.words.sort((a,b)=>a.x-b.x);let line='',prev;for(const w of row.words){if(prev){const gap=w.x-prev.x-prev.width;line+=gap>15?'  ':gap>1.5?' ':'';}line+=w.text;prev=w;}return line;});}
function timeout(promise,message,ms=60000){let timer;return Promise.race([promise,new Promise((_,reject)=>timer=setTimeout(()=>reject(new Error(message)),ms))]).finally(()=>clearTimeout(timer));}
async function getOcrWorker(){if(!ocrWorker){if(!globalThis.Tesseract)throw new Error('OCRを読み込めませんでした。ページを再読み込みしてください。');ocrWorker=await timeout(Tesseract.createWorker('jpn',1,{workerPath:new URL('vendor/tesseract/worker.min.js',root).href,corePath:new URL('vendor/tesseract-core/',root).href,langPath:new URL('vendor/tessdata-best/',root).href,cachePath:'agentic-jpn-full-v1',logger:message=>{if(message.status==='recognizing text')progress('日本語OCRで読取中… '+Math.round(message.progress*100)+'%');}}),'日本語OCRの準備がタイムアウトしました。通信を確認してください。');await ocrWorker.setParameters({tessedit_pageseg_mode:'6',preserve_interword_spaces:'1'});}return ocrWorker;}
function deskew(canvas){const small=document.createElement('canvas');small.width=Math.round(canvas.width/4);small.height=Math.round(canvas.height/4);const ctx=small.getContext('2d',{willReadFrequently:true});let bestScore=-1,bestAngle=0;for(let angle=-4;angle<=4;angle+=.5){ctx.fillStyle='white';ctx.fillRect(0,0,small.width,small.height);ctx.save();ctx.translate(small.width/2,small.height/2);ctx.rotate(angle*Math.PI/180);ctx.drawImage(canvas,-small.width/2,-small.height/2,small.width,small.height);ctx.restore();const data=ctx.getImageData(0,0,small.width,small.height).data;let sum=0,sumSquares=0;for(let y=0;y<small.height;y++){let row=0;for(let x=0;x<small.width;x++)row+=255-data[(y*small.width+x)*4];sum+=row;sumSquares+=row*row;}const score=sumSquares/small.height-(sum/small.height)**2;if(score>bestScore){bestScore=score;bestAngle=angle;}}if(bestAngle===0)return canvas;const corrected=document.createElement('canvas');corrected.width=canvas.width;corrected.height=canvas.height;const full=corrected.getContext('2d');full.fillStyle='white';full.fillRect(0,0,canvas.width,canvas.height);full.translate(canvas.width/2,canvas.height/2);full.rotate(bestAngle*Math.PI/180);full.drawImage(canvas,-canvas.width/2,-canvas.height/2);return corrected;}
async function readDocument(file,pageBudget){
  const doc=await openPdf(file.bytes);let lines=[],ocr=false;
  try{if(doc.numPages>pageBudget)throw new Error('PDFは合計10ページ以下にしてください。');for(let number=1;number<=doc.numPages;number++){progress(`${file.name} · ${number}/${doc.numPages}ページを読取中…`);const page=await doc.getPage(number);const text=await page.getTextContent();const ls=textLines(text.items);if(ls.join('').trim().length>=30){lines.push(...ls);}else{ocr=true;progress(file.name+' · 日本語OCRを準備中…');const view=page.getViewport({scale:Math.min(4.167,3500/page.getViewport({scale:1}).height)});if(view.width*view.height>15000000)throw new Error('ページが大きすぎます。通常のA4程度のPDFを選んでください。');const canvas=document.createElement('canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;const worker=await getOcrWorker();const recognized=await timeout(worker.recognize(deskew(cleanScan(canvas))),'OCRの読み取りがタイムアウトしました。');lines.push(...recognized.data.text.split('\n').filter(l=>l.trim()));canvas.width=canvas.height=1;}page.cleanup();}return {document:{name:file.name,lines,ocr},pages:doc.numPages};}finally{await doc.loadingTask.destroy();}
}
async function inputs(){if(document.querySelector('[name=source]:checked').value==='sample'){return Promise.all(samples.filter(([,scan])=>!scan||$('include-scans').checked).map(async([name])=>{const response=await fetch(new URL('data/invoices/'+name,root));if(!response.ok)throw new Error('サンプルPDFを読み込めませんでした。');return {name,bytes:await response.arrayBuffer()};}));}const files=[...$('pdf-files').files];if(files.length<1||files.length>5)throw new Error('PDFは1〜5件を選択してください。');if(files.reduce((sum,f)=>sum+f.size,0)>10*1024*1024)throw new Error('PDFの合計サイズは10MB以下にしてください。');if(files.some(f=>!f.name.toLowerCase().endsWith('.pdf')))throw new Error('PDFファイルを選んでください。');return Promise.all(files.map(async f=>({name:f.name,bytes:await f.arrayBuffer()})));}
function renderTable(){const query=$('search').value.trim().toLowerCase();const filter=$('review-filter').value;const records=(result?.records??[]).filter(r=>(!query||(r.file+' '+(r.vendor??'')).toLowerCase().includes(query))&&(!filter||(filter==='review'?r.needs_review:filter==='overdue'?r.days!=null&&r.days<0:r.days!=null&&r.days>=0&&r.days<=7)));const frag=document.createDocumentFragment();for(const record of records){const tr=document.createElement('tr');if(record.status==='期限超過')tr.className='row-overdue';const due=cell(record.due_date);const small=document.createElement('small');small.append(badge(record.status,record.status==='期限超過'?'bad':record.status==='7日以内'?'warn':''));due.append(small);const vendor=cell(record.vendor);const filename=document.createElement('small');filename.textContent=record.file;vendor.append(filename);const amount=cell(currency(record.total));amount.className='money';const review=cell('');review.append(badge(record.needs_review?'要確認':'項目取得済み',record.needs_review?'warn':'good'));const detail=cell('');const button=document.createElement('button');button.className='row-link';button.type='button';button.textContent='詳細 ↗';button.addEventListener('click',()=>showDetail(record));detail.append(button);tr.append(due,vendor,amount,cell(record.category),review,cell(record.method.startsWith('OCR')?'日本語OCR':record.method==='error'?'読取エラー':'PDFテキスト'),detail);frag.append(tr);}$('table-body').replaceChildren(frag);$('empty').classList.toggle('hidden',records.length>0);$('empty').textContent=result?'条件に一致する請求書はありません。':'「PDFを読み取る」を押すと結果が表示されます。';$('table-count').textContent=result?`${records.length} / ${result.records.length} 件を表示`:'未実行';}
function render(){ $('count-input').textContent=result.records.length;$('count-total').textContent=currency(result.total);$('count-deadline').textContent=result.overdue_count+' / '+result.soon_count;$('count-review').textContent=result.review_count;$('deadline-note').textContent='基準日 '+result.today;$('result-state').textContent='PDF読取・ブラウザで処理済み';renderTable();}
$('run').addEventListener('click',async()=>{clearError();result=null;lock(true);progress('PDFを準備しています…');try{if(!$('today').value)throw new Error('期日判定の基準日を指定してください。');sourceFiles=await inputs();const documents=[];let usedPages=0;for(const file of sourceFiles){try{const read=await readDocument(file,10-usedPages);usedPages+=read.pages;documents.push(read.document);}catch(e){if(/ページ|大きすぎ/.test(e.message))throw e;documents.push({name:file.name,lines:[],error:e.message});if(ocrWorker){await ocrWorker.terminate();ocrWorker=undefined;}}}if(documents.every(d=>d.error))throw new Error(documents[0].error);progress('項目を抽出し、支払期日順のExcelを作成中…');result=await engine.request({tool:'invoices',documents,today:$('today').value,self_name:$('self-name').value});render();}catch(e){showError(e.message);$('result-state').textContent='読み取りを完了できませんでした。';renderTable();}finally{if(ocrWorker){await ocrWorker.terminate();ocrWorker=undefined;}progress('');lock(false);}});
function showDetail(record){selectedRecord=record;$('detail-title').textContent=record.vendor??record.file;const bank=record.bank;const entries=[['ファイル',record.file],['請求日',record.invoice_date],['支払期日',record.due_date],['請求額',currency(record.total)],['銀行 / 支店',[bank.bank,bank.branch].filter(Boolean).join(' / ')],['種別 / 口座番号',[bank.type,bank.number].filter(Boolean).join(' / ')],['口座名義',bank.holder],['勘定科目（推定）',record.category],['品目',record.items.join(' / ')],['抽出方法',record.method]];$('detail-grid').replaceChildren();for(const [label,value] of entries){const div=document.createElement('div');const dt=document.createElement('dt');dt.textContent=label;const dd=document.createElement('dd');dd.textContent=value||'未取得';div.append(dt,dd);$('detail-grid').append(div);}$('detail-notes').replaceChildren();for(const note of record.notes){const li=document.createElement('li');li.textContent=note;$('detail-notes').append(li);}$('raw-text').textContent=record.lines.join('\n')||'テキストを取得できませんでした。';$('detail-dialog').showModal();}
$('close-detail').addEventListener('click',()=>$('detail-dialog').close());$('close-preview').addEventListener('click',()=>$('preview-dialog').close());
async function renderPreview(){if(!previewDoc||previewBusy)return;previewBusy=true;$('preview-page').disabled=true;$('preview-status').textContent='表示中…';try{const page=await previewDoc.getPage(Number($('preview-page').value));const view=page.getViewport({scale:Math.min(1.5,1000/page.getViewport({scale:1}).width)});const canvas=$('preview-canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;$('preview-status').textContent='';}catch{$('preview-status').textContent='原本を表示できませんでした。';}finally{previewBusy=false;$('preview-page').disabled=false;}}
$('preview').addEventListener('click',async()=>{const file=sourceFiles.find(f=>f.name===selectedRecord?.file);if(!file)return;$('preview-dialog').showModal();$('preview-status').textContent='PDFを読み込み中…';try{if(previewDoc){await previewDoc.loadingTask.destroy();previewDoc=undefined;}previewDoc=await openPdf(file.bytes);$('preview-page').replaceChildren();for(let number=1;number<=previewDoc.numPages;number++){const option=document.createElement('option');option.value=number;option.textContent=number+' / '+previewDoc.numPages;$('preview-page').append(option);}await renderPreview();}catch(e){$('preview-status').textContent=e.message;}});
$('preview-page').addEventListener('change',renderPreview);
document.querySelectorAll('[name=source]').forEach(input=>input.addEventListener('change',()=>{const sample=input.value==='sample';$('sample-box').classList.toggle('hidden',!sample);$('upload-box').classList.toggle('hidden',sample);invalidate();}));
for(const id of ['include-scans','today','self-name'])$(id).addEventListener('change',invalidate);
$('include-scans').addEventListener('change',()=>{const ls=$('sample-list');ls.replaceChildren();const names=[['つばめ架空通信',false],['ひまわり架空広告',false],['あおい架空デザイン',true],['かもめ架空不動産',true],['こばと架空文具',false]];for(const [name,scan] of names){if(scan&&!$('include-scans').checked)continue;const li=document.createElement('li');li.textContent=name+' / '+(scan?'スキャンPDF':'テキストPDF');ls.append(li);}$('sample-box').querySelector('strong').textContent='架空の請求書'+($('include-scans').checked?'5':'3')+'件';});
$('pdf-files').addEventListener('change',()=>{$('uploaded-list').replaceChildren();for(const file of $('pdf-files').files){const li=document.createElement('li');li.textContent=file.name;$('uploaded-list').append(li);}invalidate();});
$('search').addEventListener('input',renderTable);$('review-filter').addEventListener('change',renderTable);$('retry').addEventListener('click',()=>engine.start());wireDownloads(()=>result,'invoice_payments');renderTable();
function cleanScan(canvas){
  const ctx=canvas.getContext('2d',{willReadFrequently:true});
  const image=ctx.getImageData(0,0,canvas.width,canvas.height);
  const width=canvas.width,height=canvas.height;
  const black=new Uint8Array(width*height);
  for(let i=0;i<black.length;i++)black[i]=image.data[i*4]<185?1:0;
  for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++){
    const i=y*width+x;
    const count=black[i-width-1]+black[i-width]+black[i-width+1]+black[i-1]+black[i]+black[i+1]+black[i+width-1]+black[i+width]+black[i+width+1];
    const value=count>=5?0:255;
    image.data[i*4]=image.data[i*4+1]=image.data[i*4+2]=value;
  }
  ctx.putImageData(image,0,0);
  return canvas;
}
